def generate_inputs(device):
    x = torch.zeros(128, 3, 16, 32, 32, device=device, dtype=torch.float32)
    # Batch 0 stays zero - will produce minimal conv_transpose output
    # Other batches get checkerboard extreme pattern to ensure large magnitude output
    for b in range(1, 128):
        # Create 3D checkerboard pattern with extreme values
        for c in range(3):
            for d in range(16):
                for h in range(32):
                    for w in range(32):
                        sign = 1 if (d + h + w) % 2 == 0 else -1
                        x[b, c, d, h, w] = sign * 100.0
    return [x]
